for n in r.findall('node'):
 print('POI node',n.attrib,'rows',len(n.findall('row')))
 for row in n.findall('row'):
  print([resolve(x).get('fmt',resolve(x).text) for x in row if x.tag in ['event-time','signpost-name','os-log-metadata']])
